const countTraceDeliveries = `-- name: CountTraceDeliveries :many
WITH statuses AS (
    SELECT 'pending'::TEXT AS status UNION ALL SELECT 'running'::TEXT
    UNION ALL SELECT 'accepted'::TEXT UNION ALL SELECT 'failed'::TEXT
)
SELECT statuses.status, count(delivery.delivery_id)::BIGINT AS count
FROM statuses LEFT JOIN trace_deliveries AS delivery ON delivery.status = statuses.status
GROUP BY statuses.status ORDER BY statuses.status
`

type CountTraceDeliveriesRow struct {
	Status string `json:"status"`
	Count  int64  `json:"count"`
}

func (q *Queries) CountTraceDeliveries(ctx context.Context) ([]CountTraceDeliveriesRow, error) {
	rows, err := q.db.QueryContext(ctx, countTraceDeliveries)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CountTraceDeliveriesRow{}
	for rows.Next() {
		var i CountTraceDeliveriesRow
		if err := rows.Scan(&i.Status, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

