const upsertSubagent = `-- name: UpsertSubagent :one
INSERT INTO subagents (
    session_id,
    id,
    turn_id,
    display_name,
    status,
    summary,
    activity_count,
    started_at,
    updated_at,
    completed_at
) VALUES (
    $1,
    $2,
    $3,
    COALESCE(NULLIF($4, ''), $2),
    $5,
    $6,
    $7,
    $8,
    $9,
    $10
)
ON CONFLICT (session_id, id) DO UPDATE
SET turn_id = COALESCE(EXCLUDED.turn_id, subagents.turn_id),
    display_name = CASE
      WHEN $4 = '' THEN subagents.display_name
      ELSE EXCLUDED.display_name
    END,
    status = EXCLUDED.status,
    summary = CASE
      WHEN EXCLUDED.summary IS NULL THEN subagents.summary
      ELSE EXCLUDED.summary
    END,
    activity_count = CASE
      WHEN EXCLUDED.activity_count > subagents.activity_count THEN EXCLUDED.activity_count
      ELSE subagents.activity_count
    END,
    updated_at = EXCLUDED.updated_at,
    completed_at = EXCLUDED.completed_at
RETURNING session_id, id, turn_id, display_name, status, summary, activity_count, started_at, updated_at, completed_at
`

type UpsertSubagentParams struct {
	SessionID     uuid.UUID   `json:"session_id"`
	ID            string      `json:"id"`
	TurnID        *uuid.UUID  `json:"turn_id"`
	DisplayName   interface{} `json:"display_name"`
	Status        string      `json:"status"`
	Summary       null.String `json:"summary"`
	ActivityCount int64       `json:"activity_count"`
	StartedAt     time.Time   `json:"started_at"`
	UpdatedAt     time.Time   `json:"updated_at"`
	CompletedAt   null.Time   `json:"completed_at"`
}

func (q *Queries) UpsertSubagent(ctx context.Context, arg UpsertSubagentParams) (Subagent, error) {
	row := q.db.QueryRowContext(ctx, upsertSubagent,
		arg.SessionID,
		arg.ID,
		arg.TurnID,
		arg.DisplayName,
		arg.Status,
		arg.Summary,
		arg.ActivityCount,
		arg.StartedAt,
		arg.UpdatedAt,
		arg.CompletedAt,
	)
	var i Subagent
	err := row.Scan(
		&i.SessionID,
		&i.ID,
		&i.TurnID,
		&i.DisplayName,
		&i.Status,
		&i.Summary,
		&i.ActivityCount,
		&i.StartedAt,
		&i.UpdatedAt,
		&i.CompletedAt,
	)
	return i, err
}
